<span style="display:flex;gap:6px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="flex:1;text-align:center;font-size:11px;color:#444"></span>
  <button onclick="nextStep()">▶</button>
</span>
<button id="flowBtn" onclick="trigger_flowAnimation()">▶ Play fluid flow</button>
<label>Process stage:
  <select id="phaseInput" onchange="update_phase(this.value)">
    <option value="idle">idle</option>
    <option value="water down">water down</option>
    <option value="sulfur melts">sulfur melts</option>
    <option value="air down">air down</option>
