    <option value="recovered at surface">recovered at surface</option>
  </select>
</label>
<label>Injected water temperature (°C): <output id="waterTempVal">170</output>
  <input id="waterTempInput" type="range" min="80" max="200" step="5" value="170"
    oninput="document.getElementById('waterTempVal').value=this.value;update_waterTemp(+this.value)">
</label>
<span id="tempNote" style="font-size:10.5px;color:#666"></span>
<span style="font-size:10.5px;color:#777;line-height:1.4">Hover a pipe, the casing, the soil or the melt pool for its role; click for a longer explanation.</span>
