  gFill.rect(xoR - xoL, yCaseB - yOuterT).move(xoL, yOuterT).fill(pipeGrad);     // main column
  gFill.rect(600 - xoR, yBrB - yBrT).move(xoR, yBrT).fill(pipeGrad);             // water inlet branch
  gFill.rect(xiR - xiL, yHeadT).move(xiL, 8).fill('#ffffff');                    // air pipe above head

  // ───────── hover regions ─────────
  var regions = [
    { x: xoL, y: yOuterT, w: xmL - xoL, h: yCaseB - yOuterT, col: C.water, key: 'water' },
    { x: xmR, y: yOuterT, w: xoR - xmR, h: yCaseB - yOuterT, col: C.water, key: 'water' },
    { x: xmL, y: yHeadB, w: xiL - xmL, h: yMidB - yHeadB, col: C.sulfur, key: 'froth' },
    { x: xiR, y: yHeadB, w: xmR - xiR, h: yMidB - yHeadB, col: C.sulfur, key: 'froth' },
