  ];
  regions.forEach(function (r) { r.hi = gHi.rect(r.w, r.h).move(r.x, r.y).fill(r.col).opacity(0); });

  // ───────── animated streams ─────────
  var streams = [];
  function stream(key, d, col, speed, width) {
    var p = gStream.path(d).fill('none')
      .stroke({ color: col, width: width || 9, linecap: 'round', dasharray: '16 22' })
      .opacity(0.65).attr('display', 'none');
    var s = { key: key, el: p, speed: speed, off: 0, on: false };
    streams.push(s); return s;
  }
  stream('water', 'M648,450 L462,450 C430,450 412,462 412,492 L412,1150', C.water, 95);
  stream('water', 'M246,402 L246,1150', C.water, 95);
  stream('air', 'M648,26 L364,26 Q328,26 328,72 L328,972 Q328,1030 300,1046', C.air, 145, 8);
  stream('froth', 'M288,1046 L288,214 C288,186 268,180 248,180 L46,180', C.sulfur, 72);
  stream('froth', 'M367,1046 L367,222', C.sulfur, 72);
  stream('froth', 'M266,1200 C272,1146 284,1104 292,1062', C.sulfur, 72, 7);
  stream('froth', 'M390,1200 C384,1146 372,1104 364,1062', C.sulfur, 72, 7);

  // ───────── pipe outlines ─────────
  var ink = { color: C.ink, width: 3.2, linecap: 'butt', linejoin: 'miter' };
  gPipe.path('M215,145 L215,130 L441,130 L441,245 L384,245').fill('none').stroke(ink);
  gPipe.path('M215,145 L118,145').fill('none').stroke(ink);
  gPipe.path('M118,215 L215,215 L215,245 L272,245').fill('none').stroke(ink);
  gPipe.line(xmL, yHeadB, xmL, yMidB).stroke(ink);
  gPipe.line(xmR, yHeadB, xmR, yMidB).stroke(ink);
  gPipe.line(xoL, yOuterT, xoR, yOuterT).stroke(ink);
  gPipe.line(xoL, yOuterT, xoL, yCaseT + 10).stroke(ink);
  gPipe.line(xoR, yOuterT, xoR, yBrT).stroke(ink);
  gPipe.line(xoR, yBrB, xoR, yCaseT + 10).stroke(ink);
  gPipe.line(xoR, yBrT, 600, yBrT).stroke(ink);
  gPipe.line(xoR, yBrB, 600, yBrB).stroke(ink);
