  gPipe.path('M600,45 L398,45 Q351,45 351,92 L351,' + yInnB).fill('none').stroke(ink);
  gPipe.path('M305,' + (yInnB - 4) + ' C305,1048 287,1048 287,' + (yInnB - 4)).fill('none').stroke(ink);
  gPipe.path('M351,' + (yInnB - 4) + ' C351,1048 369,1048 369,' + (yInnB - 4)).fill('none').stroke(ink);
  gPipe.polygon([[xoL, yCaseT], [xoL + 12, yCaseT + 32], [xoL + 12, yCaseB], [xoL, yCaseB]]).fill('#000');
  gPipe.polygon([[xoR, yCaseT], [xoR - 12, yCaseT + 32], [xoR - 12, yCaseB], [xoR, yCaseB]]).fill('#000');

  // ───────── flow arrows (static, as in the source figure) ─────────
  [[288, 332, 288, 274], [367, 332, 367, 274],
  [288, 848, 288, 782], [367, 848, 367, 782],
  [288, 992, 288, 926], [367, 992, 367, 926],
