  [[246, 566, 246, 656], [411, 566, 411, 656],
  [246, 1048, 246, 1138], [411, 1048, 411, 1138],
  [328, 498, 328, 596]].forEach(function (a) { arrow(gArrow, a[0], a[1], a[2], a[3]); });
  arrow(gArrow, 596, 32, 452, 32);          // compressed air in
  arrow(gArrow, 596, 450, 462, 450);        // superheated water in
  arrow(gArrow, 168, 180, 46, 180);         // product out
  gArrow.path('M270,1208 C276,1150 288,1112 296,1074').fill('none').stroke({ color: C.ink, width: 3.2 });
  headAt(gArrow, 296, 1074, 8, -38);
  gArrow.path('M386,1208 C380,1150 368,1112 360,1074').fill('none').stroke({ color: C.ink, width: 3.2 });
  headAt(gArrow, 360, 1074, -8, -38);

  // ───────── labels ─────────
  var outHi = gLabel.rect(196, 78).move(20, 88).radius(8).fill(C.sulfur).opacity(0.22).attr('display', 'none');
  T(gLabel, 452, 78, 'Compressed air', 22);
  T(gLabel, 34, 114, 'Sulfur, water,', 22);
  T(gLabel, 34, 147, 'and air', 22);
  T(gLabel, 452, 372, 'Superheated', 22);
  T(gLabel, 452, 404, 'water', 22);
  var tempRead = T(gLabel, 452, 512, 'at 170 °C and 10 atm', 16, '#1d5aa0');
  T(gLabel, 84, 684, 'Soil', 22);
  gLabel.line(104, 700, 104, 764).stroke({ color: '#000', width: 2.6 });
  T(gLabel, 494, 1038, 'Solid sulfur', 22);
  T(gLabel, 494, 1070, 'deposit', 22);
  T(gLabel, cx, 1248, 'Liquid sulfur', 22, '#111', 'middle');

  // annotations
  T(gLabel, 22, 258, 'product is 99.5–99.9% pure', 13, '#444');
  T(gLabel, 22, 276, 'on cooling — no underground', 13, '#444');
  T(gLabel, 22, 294, 'mining, no miners below', 13, '#444');
  T(gLabel, 22, 602, 'sulfur melts at 115 °C;', 13, '#444');
  T(gLabel, 22, 620, 'water at 170 °C and 10 atm', 13, '#444');
  T(gLabel, 22, 638, 'stays liquid (pressurised)', 13, '#444');

  // legend
  T(gLabel, 24, 428, 'Flow key', 14, '#333', 'start', true);
  [[C.water, 'Superheated water ↓'], [C.air, 'Compressed air ↓'], [C.sulfur, 'Sulfur froth ↑']]
    .forEach(function (row, i) {
      var y = 452 + i * 25;
      gLabel.rect(22, 11).move(24, y - 10).fill(row[0]).stroke({ color: '#666', width: 0.8 });
      T(gLabel, 54, y, row[1], 14, '#333');
