  var st1 = T(gLabel, 22, 1104, '', 15, '#b00020', 'start', true).attr('display', 'none');
  var st2 = T(gLabel, 22, 1126, '', 15, '#b00020', 'start', true).attr('display', 'none');

  // ───────── hotspots ─────────
  function hotspot(x, y, w, h, tip, title, body, hi) {
    var r = gHot.rect(w, h).move(x, y).fill('#fff').opacity(0.001).attr('pointer-events', 'all').css('cursor', 'pointer');
    r.on('mousemove', function (e) { showTooltip(tip, e); if (hi) hi.opacity(0.22); });
    r.on('mouseleave', function () { hideTooltip(); if (hi) hi.opacity(0); });
    r.on('click', function () { showPopup(title, body); });
    return r;
  }
  hotspot(regions[0].x, regions[0].y, regions[0].w, regions[0].h,
    'Outer annulus — superheated water flows DOWN',
    'Outer pipe: superheated water',
    'Water at about 170 °C and 10 atm is pumped down the outermost annulus. The pressure keeps it liquid far above 100 °C, and it escapes through openings at the bottom of the casing to melt the sulfur in place.', regions[0].hi);
  hotspot(regions[1].x, regions[1].y, regions[1].w, regions[1].h,
    'Outer annulus — superheated water flows DOWN',
    'Outer pipe: superheated water',
    'Water at about 170 °C and 10 atm is pumped down the outermost annulus. The pressure keeps it liquid far above 100 °C, and it escapes through openings at the bottom of the casing to melt the sulfur in place.', regions[1].hi);
  hotspot(regions[2].x, regions[2].y, regions[2].w, regions[2].h,
    'Middle annulus — sulfur/water/air froth rises UP',
    'Middle pipe: the product line',
    'Molten sulfur enters the intake just above the melt pool and is aerated by compressed air. The froth is much less dense than water, so it is pushed up this annulus and out at the wellhead — counterflowing past the hot water descending just outside it.', regions[2].hi);
  hotspot(regions[3].x, regions[3].y, regions[3].w, regions[3].h,
    'Middle annulus — sulfur/water/air froth rises UP',
    'Middle pipe: the product line',
    'Molten sulfur enters the intake just above the melt pool and is aerated by compressed air. The froth is much less dense than water, so it is pushed up this annulus and out at the wellhead — counterflowing past the hot water descending just outside it.', regions[3].hi);
  hotspot(regions[4].x, regions[4].y, regions[4].w, regions[4].h,
    'Innermost pipe — compressed air flows DOWN to the U-bend',
    'Inner pipe: compressed air',
    'Compressed air is forced down the innermost pipe and turns at the U-shaped manifold at the bottom. Bubbling it into the molten sulfur lowers the density of the mixture so the well itself lifts the product to the surface.', regions[4].hi);
  hotspot(200, yCaseT, 44, yCaseB - yCaseT, 'Borehole casing (steel)', 'Cased borehole',
    'The heavy black bars are the steel casing that lines the hole through soil and deposit. It keeps the strata out of the pipe annuli and confines the hot water to the sulfur-bearing zone.');
  hotspot(412, yCaseT, 44, yCaseB - yCaseT, 'Borehole casing (steel)', 'Cased borehole',
    'The heavy black bars are the steel casing that lines the hole through soil and deposit. It keeps the strata out of the pipe annuli and confines the hot water to the sulfur-bearing zone.');
  hotspot(0, ySoil, 200, yDep - ySoil, 'Soil / overburden — never excavated', 'Soil overburden',
    'The Frasch process drills through the overburden instead of removing it. Because everything happens as a fluid inside the well, the deposit is never opened and no one goes underground.');
  hotspot(456, yDep + 90, 200, 180, 'Solid sulfur deposit (melts at 115 °C)', 'Solid sulfur deposit',
    'Sulfur deposits sit hundreds of metres down, often under quicksand or limestone. Sulfur melts at only 115 °C, which is what makes fluid recovery with 170 °C water possible.');
  hotspot(228, 1120, 200, 130, 'Melt pool — liquid sulfur drawn to the intake', 'Melt pool',
    'Hot water spreading out from the bottom of the casing melts a pool of liquid sulfur around the well. The pool grows with the water temperature; below 115 °C it never forms at all.');
  hotspot(xoL, yHeadT, xoR - xoL, yHeadB - yHeadT, 'Wellhead — froth leaves here and cools', 'Wellhead recovery',
    'The sulfur–water–air mixture leaves the wellhead through the left outlet, where it is allowed to cool. The sulfur solidifies at 99.5–99.9% purity and needs no further refining.');

  // ───────── state ─────────
  var phase = 'idle', temp = 170, playing = false, meltActive = false;

  function setPlaying(on) {
    playing = on;
    var b = document.getElementById('flowBtn');
    if (b) b.textContent = playing ? '❚❚ Pause fluid flow' : '▶ Play fluid flow';
  }
  window.trigger_flowAnimation = function () {
    if (phase === 'idle' && !playing) { document.getElementById('phaseInput').value = 'froth rises'; update_phase('froth rises'); return; }
    setPlaying(!playing);
  };

  window.update_phase = function (name) {
    phase = name;
    var show = { water: false, air: false, froth: false };
    if (name === 'water down' || name === 'sulfur melts') { show.water = true; }
    else if (name === 'air down') { show.water = true; show.air = true; }
    else if (name === 'froth rises' || name === 'recovered at surface') { show.water = show.air = show.froth = true; }
    streams.forEach(function (s) { s.on = !!show[s.key]; s.el.attr('display', s.on ? null : 'none'); });
    meltActive = (name === 'sulfur melts' || name === 'air down' || name === 'froth rises' || name === 'recovered at surface');
    outHi.attr('display', name === 'recovered at surface' ? null : 'none');
    setPlaying(name !== 'idle');
    updateMelt();
  };

  window.update_waterTemp = function (v) { temp = v; updateMelt(); };

  function updateMelt() {
    var melting = meltActive && temp >= 115;
    var f = Math.max(0, Math.min(1, (temp - 115) / 85));
    if (melting) {
      meltEl.attr('display', null).radius(70 + f * 180, 52 + f * 115).center(cx, 1232).opacity(0.5 + 0.5 * f);
    } else {
      meltEl.attr('display', 'none');
    }
    tempRead.plain('at ' + temp + ' °C and 10 atm').fill(temp >= 115 ? '#1d5aa0' : '#b00020');
    var note = document.getElementById('tempNote');
    if (phase === 'idle') {
      st1.attr('display', 'none'); st2.attr('display', 'none');
    } else if (temp < 115) {
      st1.attr('display', null).plain('water ' + temp + ' °C  <  115 °C').fill('#b00020');
      st2.attr('display', null).plain('deposit stays SOLID — no flow').fill('#b00020');
    } else {
      st1.attr('display', null).plain('water ' + temp + ' °C  >  115 °C').fill('#8a5a06');
      st2.attr('display', null).plain('melt pool forming').fill('#8a5a06');
    }
    if (note) {
      note.textContent = temp < 115
        ? 'Below sulfur\u2019s 115 °C melting point: nothing melts, the well produces nothing.'
        : 'Above 115 °C: sulfur liquefies; the pool grows with temperature.';
      note.style.color = temp < 115 ? '#b00020' : '#666';
    }
  }

  // ───────── animation loop ─────────
  var last = performance.now();
  function tick(now) {
    var dt = Math.min(0.05, (now - last) / 1000); last = now;
    if (playing) {
      for (var i = 0; i < streams.length; i++) {
        var s = streams[i];
        if (!s.on) continue;
        s.off -= s.speed * dt;
        s.el.attr('stroke-dashoffset', s.off);
      }
    }
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);

  // ───────── demo step player ─────────
  var steps = [
    { title: 'The well before startup', narration: 'Three concentric pipes are cased down through soil into a solid sulfur deposit. Nothing is flowing yet — the sulfur is a hard yellow solid around the pipe bottom.', state: { phase: 'idle', waterTemp: 170 } },
    { title: 'Superheated water goes down', narration: 'Water at 170 °C and 10 atm is pumped down the outermost annulus. The pressure keeps it liquid far above its normal boiling point, and it exits through openings at the bottom into the deposit.', state: { phase: 'water down', waterTemp: 170 } },
    { title: 'Too cool to work', narration: 'Drop the injected water to 100 °C: it is below sulfur\u2019s 115 °C melting point, the deposit stays solid, and no melt pool forms. The entire process hinges on this one physical property.', state: { phase: 'sulfur melts', waterTemp: 100 } },
    { title: 'The deposit melts', narration: 'Back at 170 °C, a growing pool of molten sulfur collects at the base of the well — a purely physical change, no chemistry and no miners underground.', state: { phase: 'sulfur melts', waterTemp: 170 } },
    { title: 'Compressed air goes down the core', narration: 'Air is forced down the innermost pipe and turns at the U-shaped manifold, injecting bubbles directly into the molten sulfur at the intake.', state: { phase: 'air down', waterTemp: 170 } },
    { title: 'Froth rises up the middle pipe', narration: 'Aerated liquid sulfur is far less dense than water, so the froth is pushed up the middle annulus — counterflowing past the hot water descending just outside it.', state: { phase: 'froth rises', waterTemp: 170 } },
    { title: 'Recovery at the surface', narration: 'The sulfur–water–air mixture leaves at the wellhead, cools, and solidifies as sulfur of 99.5–99.9% purity with no further refining.', state: { phase: 'recovered at surface', waterTemp: 170 } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur];
    var ti = document.getElementById('waterTempInput');
    if (ti) { ti.value = s.state.waterTemp; document.getElementById('waterTempVal').value = s.state.waterTemp; }
    temp = s.state.waterTemp;
    var pi = document.getElementById('phaseInput');
    if (pi) pi.value = s.state.phase;
    update_phase(s.state.phase);
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length + ' — ' + s.title;
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
